package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import com.ruoyi.paicli.configuration.PcProperties;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

/** 一次性permit绑定参数、资源哈希、策略、计划、根目录、设备和fencing token。 */
public class PcToolService {
    private final PcStore store;private final PcAccess access;private final PcIdempotency idem;private final PcEvidence evidence;private final PcCrypto crypto;private final PcRunnerService runner;private final PcProperties properties;private final PcArtifactService artifacts;
    public PcToolService(PcStore s,PcAccess a,PcIdempotency i,PcEvidence e,PcCrypto c,PcRunnerService r,PcProperties p,PcArtifactService ar){store=s;access=a;idem=i;evidence=e;crypto=c;runner=r;properties=p;artifacts=ar;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> propose(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("runner:"+actor.runnerId()+":proposal",key,input,()->{
        PcRecord task=runner.lease(actor,input,false);if(Boolean.TRUE.equals(store.data(task).get("textOnly")))throw PcException.deny("纯文本问答禁止工具、文件、命令、快照和外部副作用");String callId=PcJson.text(input,"toolCallId"),name=PcJson.text(input,"toolName");if(!callId.matches("[A-Za-z0-9._:-]{1,128}"))throw PcException.invalid("工具调用ID非法");
        Map<String,Object> args=PcJson.object(input,"arguments");String hash=store.json.hash(args);if(!hash.equals(input.get("argsHash"))||!PcJson.text(input,"resourceHash").matches("[a-f0-9]{64}"))throw PcException.invalid("参数或资源哈希非法");validateBinding(task,input);if(Set.of("control__SNAPSHOT_CLEAN","control__SNAPSHOT_CLEAN_PREVIEW").contains(name))new PcSnapshotClean(store).validate(task,args);if(name.equals("control__INIT_PROJECT_MEMORY"))PcProjectRuleService.validateInit(store,task.getDirectoryContextId(),args);if(name.equals("control__SKILLS_RELOAD"))PcConnectionService.validateSkillSnapshot(store,task);
        boolean snapshotPreview=name.equals(PcSnapshotPermit.PREVIEW);Map<String,Object> definition=PcToolCatalogue.definition(name);if(definition!=null){Map<String,Object> schemaArgs=new LinkedHashMap<>(args);if(name.equals("revert_turn"))PcSnapshotPermit.FIELDS.forEach(schemaArgs::remove);PcToolCatalogue.validate(schemaArgs,PcJson.object(definition,"inputSchema"));}PcSnapshotPermit snapshots=new PcSnapshotPermit(store,artifacts);Map<String,Object> snapshotContext=null;if(snapshotPreview){if(!args.keySet().equals(Set.of("snapshotMetadataId","snapshotId","snapshotVersion")))throw PcException.invalid("内部预览只接受冻结快照三字段");snapshotContext=snapshots.validateTarget(task,args);definition=Map.of("capability","snapshot");}if(name.equals("revert_turn")){if(!args.containsKey("previewToolCallId")){Map<String,Object> selected=snapshots.select(task,args);return Map.of("toolCallId",callId,"decision","PREVIEW_REQUIRED","version",task.getVersion(),"snapshotContext",selected,"previewToolName",PcSnapshotPermit.PREVIEW,"originalArgsHash",hash);}snapshotContext=snapshots.validateRestore(task,args);if(!Objects.equals(input.get("resourceHash"),snapshotContext.get("currentFingerprint")))throw PcException.conflict("恢复resourceHash必须是预览批准的当前树指纹");}
        validateSkillResource(task,name,args,PcJson.text(input,"resourceHash"));
        String unique="task:"+task.getId()+":call:"+callId;PcRecord old=store.mapper.findKey(PcTable.TOOL_CALL,unique,true);if(old!=null){if(!hash.equals(store.data(old).get("argsHash")))throw PcException.conflict("工具调用ID已用于另一组参数");return permitView(old,task);}
        PcRecord device=store.require(PcTable.RUNNER,actor.runnerId(),false),workspace=store.require(PcTable.DIRECTORY_CONTEXT,task.getDirectoryContextId(),false);String deny=PcToolPolicy.deny(name,args,store.data(device),store.data(workspace));
        boolean control=name.startsWith("control__"),mcp=name.startsWith("mcp__");String operation=control?name.substring(9):"";
        if(!PcToolPolicy.BUILTIN.contains(name)&&!mcp&&!control&&!snapshotPreview)deny="工具未在已批准的注册表中登记";
        if(control&&(!PcToolPolicy.CONTROL.contains(operation)||!operation.equals(store.data(task).get("operation"))||!store.json.hash(args).equals(store.json.hash(store.data(task).get("arguments")))))deny="控制动作或参数不等于中心冻结的用户操作";
        
        Map<String,Object> browserDefinition=Set.of("browser_connect","browser_disconnect","browser_status").contains(name)?trustedBrowser(task):null;if(Set.of("browser_connect","browser_disconnect","browser_status").contains(name)&&browserDefinition==null)deny="浏览器没有当前目录已批准chrome-devtools绑定";
        Map<String,Object> mcpDefinition=mcp?trustedMcp(task.getDirectoryContextId(),name):null;if(mcp&&mcpDefinition==null)deny="MCP配置或工具版本未经当前哈希信任批准";if(mcpDefinition!=null&&mcpDefinition.get("inputSchema") instanceof Map<?,?>)PcToolCatalogue.validate(args,PcJson.object(mcpDefinition,"inputSchema"));if(mcp&&(!(store.data(device).get("capabilities") instanceof List<?> caps)||!caps.contains("mcp")))deny="Runner未声明MCP能力";
        if(definition!=null&&(!(store.data(device).get("capabilities") instanceof List<?> capabilities)||!capabilities.contains(definition.get("capability"))))deny="Runner没有声明该工具所需能力";
        PcRecord activeLease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);long used=store.data(activeLease).get("usedTokens") instanceof Number n?n.longValue():0;PcRecord policy=store.policy(task.getDirectoryContextId(),false);String capability=definition==null?(mcp?"mcp":control?controlCapability(operation):""):PcJson.text(definition,"capability");if(store.data(policy).get("allowedCapabilities") instanceof List<?> allowed&&!capability.isBlank()&&!allowed.contains(capability))deny="当前策略未允许该能力";long taskBudget=PcJson.number(store.data(policy),"taskTokenBudget");if(store.data(task).get("taskTokenBudget") instanceof Number budget)taskBudget=Math.min(taskBudget,budget.longValue());if(used>=taskBudget)deny="任务Token额度已用尽，不能启动新工具";if(PcJson.text(store.data(task),"source").equals("WECHAT")){Map<String,Object> wp=PcJson.object(store.data(task),"wechatPolicy");if(mcpDefinition!=null){String server=PcJson.text(store.data(store.require(PcTable.MCP_CONFIG,PcJson.number(mcpDefinition,"mcpConfigId"),false)),"name");if(!(wp.get("mcpAllowlist") instanceof List<?> allow&&allow.contains(server)&&Boolean.TRUE.equals(mcpDefinition.get("readOnly"))))deny="微信MCP工具须在允许名单内且已确认只读";}else if(!PcToolPolicy.READONLY.contains(name))deny="微信允许名单不代替参数审批，副作用工具须转中心批准";}
        if(name.equals("read_file")&&PcJson.text(args,"path").matches("\\.paicli/tool-outputs/center/[0-9]+\\.txt")){long outputId=Long.parseLong(PcJson.text(args,"path").replaceAll("^.*?/([0-9]+)\\.txt$","$1"));Map<String,Object> metadata=artifacts.runnerOutputMetadata(outputId,task.getDirectoryContextId(),task.getOwnerId(),task.getSessionId());if(!Objects.equals(input.get("resourceHash"),metadata.get("sha256")))throw PcException.conflict("工具输出资源哈希与中心产物不同");}
        if(name.equals("web_fetch")&&!allowedUrl(task,args))deny="URL未来自用户顶层输入或已确认的结构化搜索结果";
        if(Boolean.TRUE.equals(store.data(task).get("readOnly"))&&!(snapshotPreview||PcToolPolicy.READONLY.contains(name)||(mcpDefinition!=null&&Boolean.TRUE.equals(mcpDefinition.get("readOnly")))||(control&&PcToolPolicy.CONTROL_READ.contains(operation))))deny="只分析模式禁止写文件、命令和未明确只读的外部工具";
        Map<String,Object> data=new LinkedHashMap<>(input);data.remove("permitToken");data.put("taskId",String.valueOf(task.getId()));if(mcpDefinition!=null)for(String field:List.of("mcpConfigId","mcpConfigVersion","mcpConfigHash"))data.put(field,mcpDefinition.get(field));if(browserDefinition!=null)data.putAll(browserDefinition);if(snapshotContext!=null)data.put("snapshotContext",snapshotContext);data.put("readOnly",snapshotPreview||PcToolPolicy.READONLY.contains(name)||(mcpDefinition!=null&&Boolean.TRUE.equals(mcpDefinition.get("readOnly")))||(control&&PcToolPolicy.CONTROL_READ.contains(operation)));data.put("hardDenied",deny!=null);data.put("inputHash",hash);data.put("requesterName",String.valueOf(task.getOwnerId()));data.put("paths",args.get("path")==null?List.of():List.of(args.get("path")));data.put("impact",snapshotPreview||PcToolPolicy.READONLY.contains(name)?"读取授权资料":"修改文件或调用外部能力，须检查具体参数");
        boolean automaticDirectory=control&&operation.equals("DIR_PREPARE")&&args.isEmpty()&&"CONTROL".equals(store.data(task).get("source"));String state=deny!=null?"DENIED":automaticDirectory||Boolean.TRUE.equals(data.get("readOnly"))&&!Boolean.TRUE.equals(input.get("sensitive"))?"PERMITTED":"PENDING";if(deny!=null)data.put("denialReason",deny);
        PcRecord call=store.insert(PcTable.TOOL_CALL,task.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),actor.runnerId(),name,state,unique,data);
        if(state.equals("PENDING")){PcRecord approval=store.insert(PcTable.APPROVAL,task.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),actor.runnerId(),name,"PENDING",unique,data);approval.setExpiresAt(store.clock.instant().plusSeconds(properties.getApprovalSeconds()));store.save(PcTable.APPROVAL,approval,data);data.put("approvalId",String.valueOf(approval.getId()));store.save(PcTable.TOOL_CALL,call,data);}
        if(state.equals("PERMITTED"))issue(call,task);
        evidence.audit(task.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),"TOOL_PROPOSAL",state,Map.of("toolCallId",callId,"toolName",name,"argsHash",hash,"resourceHash",input.get("resourceHash")));
        evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"TOOL_PROPOSED",Map.of("toolCallId",callId,"decision",state));if(state.equals("PENDING"))evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"APPROVAL_REQUIRED",Map.of("approvalId",data.get("approvalId"),"toolCallId",callId,"toolName",name,"argsHash",hash,"resourceHash",input.get("resourceHash"),"requesterName",String.valueOf(task.getOwnerId())));return permitView(call,task);
    });}
    private Map<String,Object> trustedMcp(long workspace,String name){for(PcRecord r:store.mapper.list(PcTable.MCP_CONFIG,workspace,null,null,"READY")){Map<String,Object> p=store.data(r);if(!Objects.equals(p.get("configHash"),p.get("trustedHash")))continue;String prefix="mcp__"+PcJson.text(p,"name")+"__";if(!name.startsWith(prefix))continue;String rawName=name.substring(prefix.length());List<?> definitions=p.get("tools") instanceof List<?> list?list:List.of();for(Object t:definitions)if(t instanceof Map<?,?> m&&rawName.equals(m.get("name"))&&(!m.containsKey("namespacedName")||name.equals(m.get("namespacedName")))){Map<String,Object> result=new LinkedHashMap<>();m.forEach((k,v)->result.put(String.valueOf(k),v));if(rawName.equals("read_resource")){List<String> references=new ArrayList<>();if(p.get("resources") instanceof List<?> list)for(Object value:list)if(value instanceof Map<?,?> item&&item.get("uri")!=null)references.add(item.get("uri").toString());result.put("inputSchema",Map.of("type","object","properties",Map.of("uri",Map.of("type","string","enum",references)),"required",List.of("uri"),"additionalProperties",false));}result.put("mcpConfigId",r.getId());result.put("mcpConfigVersion",p.getOrDefault("configurationVersion",r.getVersion()));result.put("mcpConfigHash",p.get("configHash"));return result;}}return null;}
    private Map<String,Object> trustedBrowser(PcRecord task){PcRecord browser=store.mapper.findKey(PcTable.BROWSER_CONFIG,"directory:"+task.getDirectoryContextId(),false);if(browser==null)return null;Map<String,Object> p=store.data(browser);if("DISCONNECTED".equals(p.get("mode"))||p.get("mcpConfigId")==null)return null;PcRecord mcp=store.require(PcTable.MCP_CONFIG,PcJson.number(p,"mcpConfigId"),false);Map<String,Object> mp=store.data(mcp);if(!Objects.equals(mcp.getDirectoryContextId(),task.getDirectoryContextId())||!"chrome-devtools".equals(PcJson.text(mp,"name"))||!Objects.equals(mp.get("configHash"),mp.get("trustedHash")))return null;return Map.of("browserConfigId",browser.getId(),"browserConfigVersion",p.getOrDefault("configurationVersion",browser.getVersion()),"browserConfigHash",p.getOrDefault("configHash",browser.getContentHash()),"mcpConfigId",mcp.getId(),"mcpConfigVersion",mp.getOrDefault("configurationVersion",mcp.getVersion()),"mcpConfigHash",mp.get("configHash"));}
    private void validateMcp(PcRecord task,Map<String,Object> input){if(Set.of("browser_connect","browser_disconnect","browser_status").contains(PcJson.text(input,"toolName"))){Map<String,Object> current=trustedBrowser(task);if(current==null)throw PcException.conflict("浏览器绑定已停用或信任撤销");for(String key:current.keySet())if(!Objects.toString(input.get(key),"").equals(Objects.toString(current.get(key),"")))throw PcException.conflict("浏览器或关联MCP定义版本已变化");return;}if(!PcJson.text(input,"toolName").startsWith("mcp__"))return;Map<String,Object> current=trustedMcp(task.getDirectoryContextId(),PcJson.text(input,"toolName"));if(current==null)throw PcException.conflict("MCP已停用或当前hash信任已撤销");for(String key:List.of("mcpConfigId","mcpConfigVersion","mcpConfigHash"))if(!Objects.toString(input.get(key),"").equals(Objects.toString(current.get(key),"")))throw PcException.conflict("MCP定义版本已变化，旧许可失效");}
    private String controlCapability(String operation){if(Set.of("REPOSITORY_LIST","DIR_PREPARE","DIRECTORY_VERIFY").contains(operation))return "files";if(operation.startsWith("MCP_"))return "mcp";if(operation.startsWith("BROWSER_"))return "browser";if(operation.startsWith("WECHAT_"))return "wechat";if(operation.startsWith("SKILLS_"))return "skills";if(operation.startsWith("SNAPSHOT_"))return "snapshot";if(operation.startsWith("MEMORY_")||operation.equals("INIT_PROJECT_MEMORY"))return "memory";if(Set.of("INDEX_BUILD","REPOSITORY_SEARCH","AST_GRAPH").contains(operation))return "rag";return "";}
    private boolean allowedUrl(PcRecord task,Map<String,Object> args){String url=PcJson.text(args,"url");if(url.isBlank())return false;String input=PcJson.text(store.data(task),"input");if(java.util.regex.Pattern.compile("https?://[^\\s<>\"']+").matcher(input).results().anyMatch(m->m.group().equals(url)))return true;for(PcRecord receipt:store.mapper.list(PcTable.TOOL_RECEIPT,task.getDirectoryContextId(),task.getOwnerId(),task.getId(),null)){Map<String,Object> p=store.data(receipt);if(p.get("result") instanceof Map<?,?> result&&result.get("discoveredUrls") instanceof List<?> discovered&&discovered.contains(url))return true;}return false;}
    private void validateBinding(PcRecord task,Map<String,Object> input){
        PcRecord workspace=store.require(PcTable.DIRECTORY_CONTEXT,task.getDirectoryContextId(),false);if(PcJson.number(input,"policyVersion")!=store.ownerPolicy(task.getOwnerId(),false).getVersion()||!Objects.equals(input.get("rootFingerprint"),store.data(workspace).get("rootFingerprint")))throw PcException.conflict("个人策略或执行目录版本已变化");
        List<PcRecord> plans=store.mapper.list(PcTable.PLAN,task.getDirectoryContextId(),task.getOwnerId(),task.getId(),null);long expected=plans.isEmpty()?0:definition(plans.get(0));if(PcJson.number(input,"planVersion")!=expected)throw PcException.conflict("计划定义版本已变化，旧审批不可执行");
        if(expected>0&&!PcToolPolicy.READONLY.contains(PcJson.text(input,"toolName"))&&!PcSnapshotPermit.PREVIEW.equals(PcJson.text(input,"toolName"))){Map<String,Object> p=store.data(plans.get(0));if(PcJson.number(p,"approvedVersion")!=expected)throw PcException.conflict("当前计划版本未批准执行");}
    }
    private long definition(PcRecord plan){Object value=store.data(plan).get("definitionVersion");return value instanceof Number n?n.longValue():1;}
    private void validateSkillResource(PcRecord task,String name,Map<String,Object> args,String fingerprint){
        if(name.equals("load_skill")&&!PcConnectionService.approvedSkillFingerprint(store,task.getDirectoryContextId(),PcJson.text(args,"name")).equals(fingerprint))throw PcException.conflict("Skill生效层或批准版本已变化，请取得当前上下文后重新加载");
    }
    private void validateSnapshot(PcRecord task,Map<String,Object> data){String name=PcJson.text(data,"toolName");if(Set.of("control__SNAPSHOT_CLEAN","control__SNAPSHOT_CLEAN_PREVIEW").contains(name))new PcSnapshotClean(store).validate(task,PcJson.object(data,"arguments"));if(name.equals("control__INIT_PROJECT_MEMORY"))PcProjectRuleService.validateInit(store,task.getDirectoryContextId(),PcJson.object(data,"arguments"));if(name.equals("control__SKILLS_RELOAD"))PcConnectionService.validateSkillSnapshot(store,task);if(name.equals(PcSnapshotPermit.PREVIEW))new PcSnapshotPermit(store,artifacts).validateTarget(task,PcJson.object(data,"arguments"));else if(name.equals("revert_turn"))new PcSnapshotPermit(store,artifacts).validateRestore(task,PcJson.object(data,"arguments"));}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> revertContext(PcRunnerPrincipal actor,Map<String,Object> input){PcRecord task=runner.lease(actor,input,false),call=consumedTool(actor,input);if(!call.getKind().equals("revert_turn"))throw PcException.deny("恢复上下文仅属于已消费revert_turn许可");Map<String,Object> cp=store.data(call);for(String field:List.of("taskId","leaseId","fencingToken","version"))if(!Objects.toString(cp.get(field),"").equals(Objects.toString(input.get(field),"")))throw PcException.deny("恢复许可不是当前lease/attempt");Map<String,Object> context=new PcSnapshotPermit(store,artifacts).validateRestore(task,PcJson.object(cp,"arguments"));if(!store.json.hash(context).equals(store.json.hash(cp.get("snapshotContext"))))throw PcException.conflict("恢复上下文与批准时不同");Map<String,Object> response=new LinkedHashMap<>(context);response.put("arguments",cp.get("arguments"));response.put("argsHash",cp.get("argsHash"));response.put("taskId",String.valueOf(task.getId()));response.put("sessionId",String.valueOf(task.getSessionId()));response.put("directoryContextId",String.valueOf(task.getDirectoryContextId()));for(String field:List.of("leaseId","fencingToken","version"))response.put(field,cp.get(field));return response;}
    private void issue(PcRecord call,PcRecord task){Map<String,Object> p=store.data(call);String token=crypto.token("pcp_");p.put("permitHash",PcJson.digest(token));p.put("permitCipher",crypto.seal(call.getUniqueKey(),token));PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);call.setExpiresAt(lease.getExpiresAt());call.setState("PERMITTED");store.save(PcTable.TOOL_CALL,call,p);}
    private Map<String,Object> permitView(PcRecord call,PcRecord task){Map<String,Object> p=store.data(call),v=new LinkedHashMap<>();v.put("toolCallId",p.get("toolCallId"));v.put("decision",call.getState());v.put("version",task.getVersion());v.put("ownerUserId",String.valueOf(task.getOwnerId()));v.put("directoryContextId",String.valueOf(task.getDirectoryContextId()));for(String field:List.of("argsHash","resourceHash","policyVersion","planVersion","rootFingerprint","fencingToken","approvalId","denialReason","approvalDecision","feedback","revisedArguments","revisedArgsHash","snapshotContext"))if(p.containsKey(field))v.put(field,p.get(field));if(call.getExpiresAt()!=null)v.put("expiresAt",call.getExpiresAt().toString());if(call.getState().equals("PERMITTED"))v.put("permitToken",crypto.open(call.getUniqueKey(),PcJson.text(p,"permitCipher")));return v;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> permit(PcRunnerPrincipal actor,String key,Map<String,Object> input,boolean consume){return idem.run("runner:"+actor.runnerId()+":permit:"+consume,key,input,()->{
        PcRecord task=runner.lease(actor,input,false);if(Boolean.TRUE.equals(store.data(task).get("textOnly")))throw PcException.deny("纯文本问答禁止工具、文件、命令、快照和外部副作用");PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,"task:"+task.getId()+":call:"+PcJson.text(input,"toolCallId"),true);if(call==null)throw PcException.invalid("工具尚未申请许可");Map<String,Object> p=store.data(call);Map<String,Object> bound=new LinkedHashMap<>(input);bound.put("toolName",p.get("toolName"));validateBinding(task,bound);validateMcp(task,p);validateSnapshot(task,p);
        validateSkillResource(task,PcJson.text(p,"toolName"),PcJson.object(p,"arguments"),PcJson.text(p,"resourceHash"));
        for(String f:List.of("argsHash","resourceHash","policyVersion","planVersion","rootFingerprint","fencingToken"))if(!Objects.toString(p.get(f),"").equals(Objects.toString(input.get(f),"")))throw PcException.conflict("许可绑定字段已变化："+f);
        if(call.getState().equals("PENDING")){PcRecord approval=store.require(PcTable.APPROVAL,Long.parseLong(String.valueOf(p.get("approvalId"))),true);if(approval.getState().equals("APPROVED")&&approval.getExpiresAt().isAfter(store.clock.instant()))issue(call,task);else return permitView(call,task);}
        if(call.getState().equals("DENIED"))return permitView(call,task);if(!call.getState().equals("PERMITTED")||call.getExpiresAt()==null||!call.getExpiresAt().isAfter(store.clock.instant()))throw PcException.conflict("许可已消费、拒绝或过期");
        if(consume){var active=store.mapper.list(PcTable.TOOL_CALL,task.getDirectoryContextId(),null,task.getId(),"CONSUMED");boolean read=Boolean.TRUE.equals(store.data(call).get("readOnly"));if((!read&&!active.isEmpty())||(read&&(active.size()>=PcJson.number(store.data(store.policy(task.getDirectoryContextId(),false)),"maxReadTools")||active.stream().anyMatch(c->!Boolean.TRUE.equals(store.data(c).get("readOnly"))))))throw PcException.conflict("工具执行并发超过读4/写1边界");if(!PcJson.digest(PcJson.text(input,"permitToken")).equals(store.data(call).get("permitHash")))throw PcException.deny("许可凭证不匹配");call.setState("CONSUMED");store.save(PcTable.TOOL_CALL,call,store.data(call));evidence.audit(task.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),"PERMIT_CONSUME","ACCEPTED",Map.of("toolCallId",input.get("toolCallId")));}
        Map<String,Object> response=permitView(call,task);if(consume)response.put("consumed",true);return response;
    });}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> receipt(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("runner:"+actor.runnerId()+":receipt",key,input,()->{
        PcRecord task=runner.receiptTask(actor,input);boolean late=runner.lateReceipt(task,input);String unique="task:"+task.getId()+":call:"+PcJson.text(input,"toolCallId");PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,unique,true);if(call==null)throw PcException.deny("没有中心工具许可记录");Map<String,Object> cp=store.data(call);if(!PcJson.digest(PcJson.text(input,"permitToken")).equals(cp.get("permitHash"))||PcJson.number(cp,"fencingToken")!=PcJson.number(input,"fencingToken")||PcJson.number(cp,"leaseId")!=PcJson.number(input,"leaseId"))throw PcException.deny("工具回执许可凭证或原attempt绑定非法");
        PcRecord prior=store.mapper.findKey(PcTable.TOOL_RECEIPT,unique,true);if(prior!=null){if(!store.json.hash(redactReceipt(input)).equals(store.data(prior).getOrDefault("requestHash",prior.getContentHash())))throw PcException.conflict("工具回执ID重复且结果不同");return receiptAck(prior,task);}
        if(!call.getState().equals("CONSUMED"))throw PcException.conflict("许可没有在执行前消费，拒绝回执");String status=PcJson.text(input,"status");if(!Set.of("COMPLETED","FAILED","CANCELLED").contains(status))throw PcException.invalid("回执状态非法");
        if(!late){if(call.getKind().equals(PcSnapshotPermit.PREVIEW)&&status.equals("COMPLETED"))new PcSnapshotPermit(store,artifacts).parsePreview(task,PcJson.object(cp,"arguments"),PcJson.object(input,"result"),PcJson.text(input,"toolCallId"));runner.outputBudget(task,input.getOrDefault("result",Map.of()),false);}
        Map<String,Object> receiptData=redactReceipt(input);receiptData.put("requestHash",store.json.hash(redactReceipt(input)));if(artifacts!=null&&receiptData.get("result") instanceof Map<?,?>)receiptData.put("result",artifacts.storeLedgerImages(PcJson.object(receiptData,"result"),task.getDirectoryContextId(),task.getOwnerId(),task.getSessionId(),task.getId()));
        PcRecord r=store.insert(PcTable.TOOL_RECEIPT,task.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),actor.runnerId(),call.getKind(),late?"LATE_ARCHIVED":status,unique,receiptData);
        if(late){evidence.audit(task.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),"LATE_TOOL_RECEIPT","LATE_ARCHIVED",Map.of("toolCallId",input.get("toolCallId"),"receiptId",r.getId(),"originalFencingToken",input.get("fencingToken")));return receiptAck(r,task);}
        // 正式记忆写入和许可回执同事务，不让Runner本地JSON成为第二真相。
        if(call.getKind().equals("save_memory")&&status.equals("COMPLETED")&&!Boolean.TRUE.equals(cp.get("memoryHandled"))){Map<String,Object> memory=saveMemory(task,cp);cp.put("memoryResult",memory);cp.put("memoryHandled",true);}
        if(call.getKind().equals("revert_turn")&&status.equals("COMPLETED")){Map<String,Object> frozen=PcJson.object(cp,"snapshotContext");PcRecord snapshot=store.require(PcTable.SNAPSHOT,PcJson.number(frozen,"snapshotMetadataId"),true);Map<String,Object> sd=store.data(snapshot);sd.put("lastRestoredAt",store.clock.instant().toString());sd.put("restoredByTaskId",String.valueOf(task.getId()));sd.put("restoreToolCallId",input.get("toolCallId"));sd.remove("restorePreview");store.save(PcTable.SNAPSHOT,snapshot,sd);}call.setState(status);Map<String,Object> p=new LinkedHashMap<>(cp);p.put("result",receiptData.getOrDefault("result",Map.of()));p.put("finishedAt",store.clock.instant().toString());store.save(PcTable.TOOL_CALL,call,p);
        evidence.audit(task.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),"TOOL_RECEIPT",status,Map.of("toolCallId",input.get("toolCallId"),"receiptId",r.getId()));evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"TOOL_RESULT",Map.of("toolCallId",input.get("toolCallId"),"status",status,"result",receiptData.getOrDefault("result",Map.of())));return receiptAck(r,task);
    });}
    private Map<String,Object> receiptAck(PcRecord receipt,PcRecord task){Map<String,Object> result=store.view(receipt);Map<String,Object> data=store.data(receipt);result.put("accepted",true);result.put("acknowledged",true);result.put("archived",receipt.getState().equals("LATE_ARCHIVED"));result.put("taskId",String.valueOf(task.getId()));for(String field:List.of("toolCallId","leaseId","fencingToken"))result.put(field,data.get(field));result.put("currentTaskStatus",task.getState());return result;}
    private Map<String,Object> redactReceipt(Map<String,Object> input){Map<String,Object> p=new LinkedHashMap<>(input);p.remove("permitToken");p.put("permitHash",PcJson.digest(PcJson.text(input,"permitToken")));return p;}
    public Map<String,Object> approvalView(PcRecord approval){Map<String,Object> view=store.view(approval);Map<String,Object> context=approvalContext(approval);if(context!=null){if(context.get("previewArtifact") instanceof Map<?,?>){Map<String,Object> artifact=PcJson.object(context,"previewArtifact");artifact.put("contentUrl","/paicli/v1/approvals/"+approval.getId()+"/preview-text");context.put("previewArtifact",artifact);}view.put("snapshotContext",context);}return view;}
    private Map<String,Object> approvalContext(PcRecord approval){Map<String,Object> data=store.data(approval);if(approval.getKind().equals("revert_turn")&&data.get("snapshotContext") instanceof Map<?,?>)return PcJson.object(data,"snapshotContext");if(approval.getKind().equals("control__SNAPSHOT_RESTORE")){Map<String,Object> args=PcJson.object(data,"arguments"),snapshot=PcJson.object(args,"snapshot");if(snapshot.get("restorePreview") instanceof Map<?,?>){Map<String,Object> proof=PcJson.object(snapshot,"restorePreview"),context=new LinkedHashMap<>();context.put("restorePreview",proof);context.put("currentFingerprint",args.get("currentFingerprint"));context.put("snapshotMetadataId",args.get("snapshotMetadataId"));context.put("previewTaskId",snapshot.get("previewTaskId"));if(proof.containsKey("eventArtifactId"))context.put("previewArtifact",Map.of("artifactId",proof.get("eventArtifactId"),"sha256",proof.get("eventArtifactSha256"),"size",proof.get("eventArtifactSize")));return context;}}return null;}
    /** 只允许批准者读取本审批冻结的预览差异，不能借审批读取任意成员产物。 */
    public Map<String,Object> previewText(long user,long id,long offset,int limit){
        PcRecord approval=access.resource(PcTable.APPROVAL,id,user,false,false);access.approve(approval.getDirectoryContextId(),user);Map<String,Object> context=approvalContext(approval);if(context==null||!(context.get("previewArtifact") instanceof Map<?,?>))throw PcException.deny("此审批没有快照预览产物用途");Map<String,Object> reference=PcJson.object(context,"previewArtifact");long artifactId=PcJson.number(reference,"artifactId");Map<String,Object> metadata=artifacts.runnerOutputMetadata(artifactId,approval.getDirectoryContextId(),approval.getOwnerId(),approval.getSessionId());long originalTask;String callId;
        if(approval.getKind().equals("revert_turn")){callId=PcJson.text(context,"previewToolCallId");originalTask=approval.getParentId();PcRecord receipt=store.mapper.findKey(PcTable.TOOL_RECEIPT,"task:"+originalTask+":call:"+callId,false);
            if(receipt==null||!receipt.getKind().equals(PcSnapshotPermit.PREVIEW)||!receipt.getState().equals("COMPLETED")||!Objects.equals(receipt.getOwnerId(),approval.getOwnerId())||!Objects.equals(receipt.getDirectoryContextId(),approval.getDirectoryContextId())||!Objects.equals(receipt.getSessionId(),approval.getSessionId()))throw PcException.deny("此审批没有同域的正式完成预览回执");Map<String,Object> body=store.json.read(PcJson.text(PcJson.object(store.data(receipt),"result"),"text"));if(artifactId!=PcJson.number(body,"previewArtifactId")||!Objects.equals(reference.get("sha256"),body.get("previewArtifactSha256"))||PcJson.number(reference,"size")!=PcJson.number(body,"previewArtifactSize"))throw PcException.conflict("预览差异引用与冻结回执不同");
        }else if(approval.getKind().equals("control__SNAPSHOT_RESTORE")){originalTask=PcJson.number(context,"previewTaskId");callId=PcJson.text(metadata,"toolCallId");PcRecord task=store.require(PcTable.TASK,originalTask,false),call=store.mapper.findKey(PcTable.TOOL_CALL,"task:"+originalTask+":call:"+callId,false);if(!Objects.equals(task.getOwnerId(),approval.getOwnerId())||!Objects.equals(task.getDirectoryContextId(),approval.getDirectoryContextId())||!Objects.equals(task.getSessionId(),approval.getSessionId())||call==null||!call.getKind().equals("control__SNAPSHOT_PREVIEW")||!Set.of("CONSUMED","COMPLETED").contains(call.getState()))throw PcException.deny("差异不是本审批会话的正式受许可预览结果");boolean observed=store.mapper.list(PcTable.EVENT,approval.getDirectoryContextId(),approval.getOwnerId(),originalTask,null).stream().anyMatch(event->{Map<String,Object> p=store.data(event);if(!event.getKind().equals("SNAPSHOT")||!(p.get("payload") instanceof Map<?,?>))return false;Map<String,Object> payload=PcJson.object(p,"payload");return Objects.toString(payload.get("eventArtifactId"),"").equals(String.valueOf(artifactId))&&Objects.equals(payload.get("eventArtifactSha256"),reference.get("sha256"));});if(!observed)throw PcException.deny("冻结预览缺少同产物SHA的正式事件");
        }else throw PcException.deny("此审批没有快照预览用途");
        if(!String.valueOf(originalTask).equals(metadata.get("parentId"))||!callId.equals(metadata.get("toolCallId"))||!Objects.equals(metadata.get("sha256"),reference.get("sha256"))||PcJson.number(metadata,"size")!=PcJson.number(reference,"size"))throw PcException.deny("预览差异产物不属于审批的固定任务和调用");return artifacts.scopedOutputText(artifactId,approval.getDirectoryContextId(),approval.getOwnerId(),approval.getSessionId(),originalTask,callId,PcJson.text(reference,"sha256"),PcJson.number(reference,"size"),offset,limit);
    }
    public PcRecord consumedTool(PcRunnerPrincipal actor,Map<String,Object> input){PcRecord task=runner.lease(actor,input,false);if(Boolean.TRUE.equals(store.data(task).get("textOnly")))throw PcException.deny("纯文本问答禁止工具、文件、命令、快照和外部副作用");PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,"task:"+task.getId()+":call:"+PcJson.text(input,"toolCallId"),true);if(call==null||!call.getState().equals("CONSUMED")||!PcJson.digest(PcJson.text(input,"permitToken")).equals(store.data(call).get("permitHash")))throw PcException.deny("缺少已经消费的工具许可");return call;}
    public PcRecord consumedControl(PcRunnerPrincipal actor,Map<String,Object> input,String... operations){PcRecord task=runner.lease(actor,input,false);if(Boolean.TRUE.equals(store.data(task).get("textOnly")))throw PcException.deny("纯文本问答禁止工具、文件、命令、快照和外部副作用");String operation=PcJson.text(store.data(task),"operation");if(!Arrays.asList(operations).contains(operation))throw PcException.deny("控制用途不匹配");PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,"task:"+task.getId()+":call:"+PcJson.text(input,"toolCallId"),true);if(call==null||!call.getKind().equals("control__"+operation)||!call.getState().equals("CONSUMED")||!PcJson.digest(PcJson.text(input,"permitToken")).equals(store.data(call).get("permitHash")))throw PcException.deny("控制操作缺少已消费的中心许可");return task;}
    private Map<String,Object> saveMemory(PcRecord task,Map<String,Object> cp){Map<String,Object> args=PcJson.object(cp,"arguments");String scope=PcJson.text(args,"scope");boolean personal=scope.equalsIgnoreCase("global")||scope.equalsIgnoreCase("PERSONAL");return new PcKnowledgeService(store,access,idem,evidence,null).memoryWrite(task.getOwnerId(),personal?null:task.getDirectoryContextId(),task.getSessionId(),task.getId(),PcJson.text(args,"fact"),"APPROVED_TOOL","VERIFIED",args);}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> writeMemory(PcRunnerPrincipal actor,String key,Map<String,Object> input,PcKnowledgeService knowledge){return idem.run("runner:"+actor.runnerId()+":approved-memory",key,input,()->{
        PcRecord task=runner.lease(actor,input,false);if(Boolean.TRUE.equals(store.data(task).get("textOnly")))throw PcException.deny("纯文本问答禁止工具、文件、命令、快照和外部副作用");PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,"task:"+task.getId()+":call:"+PcJson.text(input,"toolCallId"),true);
        if(call==null||!call.getKind().equals("save_memory")||!call.getState().equals("CONSUMED")||!PcJson.digest(PcJson.text(input,"permitToken")).equals(store.data(call).get("permitHash")))throw PcException.deny("记忆写入缺少已经消费的save_memory许可");
        Map<String,Object> cp=store.data(call),args=PcJson.object(cp,"arguments");String fact=PcJson.text(input,"fact"),scope=memoryScope(PcJson.text(input,"scope"));if(!fact.equals(PcJson.text(args,"fact"))||!scope.equals(memoryScope(PcJson.text(args,"scope"))))throw PcException.conflict("记忆内容与已批准参数不同");
        if(!PcJson.text(input,"id").equals(PcJson.text(args,"replace_id"))||Boolean.TRUE.equals(input.get("allowConflict"))!=Boolean.TRUE.equals(args.get("keep_both")))throw PcException.conflict("替换目标或保留冲突选择与已批准参数不同");
        if(Boolean.TRUE.equals(cp.get("memoryHandled")))return PcJson.object(cp,"memoryResult");
        Map<String,Object> result=knowledge.memoryWrite(task.getOwnerId(),scope.equals("global")?null:task.getDirectoryContextId(),task.getSessionId(),task.getId(),fact,"APPROVED_TOOL","VERIFIED",args);cp.put("memoryHandled",true);cp.put("memoryResult",result);if(Set.of("STORED","REPLACED","DUPLICATE").contains(result.get("status")))cp.put("memoryId",PcJson.object(result,"entry").get("id"));store.save(PcTable.TOOL_CALL,call,cp);return result;
    });}
    private String memoryScope(String value){if(value.isBlank()||value.equalsIgnoreCase("project"))return "project";if(value.equalsIgnoreCase("global")||value.equalsIgnoreCase("PERSONAL"))return "global";throw PcException.invalid("记忆scope仅支持project/global");}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> decision(long user,long id,long version,String key,Map<String,Object> input){return idem.run("user:"+user+":approval:"+id,key,input,()->{
        PcRecord approval=access.resource(PcTable.APPROVAL,id,user,false,true);access.approve(approval.getDirectoryContextId(),user);store.version(approval,version);if(!approval.getState().equals("PENDING")||!approval.getExpiresAt().isAfter(store.clock.instant()))throw PcException.conflict("审批已处理或过期");
        Map<String,Object> p=store.data(approval);if(!Objects.equals(p.get("argsHash"),input.get("inputHash")))throw PcException.conflict("审批输入哈希已经改变");PcRecord task=store.require(PcTable.TASK,approval.getParentId(),true);validateBinding(task,p);validateMcp(task,p);validateSnapshot(task,p);
        PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);if(lease==null||!lease.getState().equals("ACTIVE")||!lease.getExpiresAt().isAfter(store.clock.instant())||lease.getFencingToken()!=PcJson.number(p,"fencingToken"))throw PcException.conflict("发起审批的租约已失效");
        String decision=PcJson.text(input,"decision");String state=switch(decision){case "APPROVE"->"APPROVED";case "REJECT"->"REJECTED";case "SKIP"->"SKIPPED";case "REVISE"->"REVISED";default->throw PcException.invalid("审批决定非法");};
        p.put("actorId",String.valueOf(user));p.put("feedback",PcJson.text(input,"feedback"));p.put("decisionAt",store.clock.instant().toString());if(state.equals("REVISED")){p.put("revisedArguments",PcJson.object(input,"revisedArguments"));p.put("revisedArgsHash",store.json.hash(p.get("revisedArguments")));}
        approval.setState(state);store.save(PcTable.APPROVAL,approval,p);if(!state.equals("APPROVED")){PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,approval.getUniqueKey(),true);call.setState("DENIED");Map<String,Object> denied=store.data(call);denied.put("approvalDecision",state);denied.put("feedback",p.get("feedback"));if(state.equals("REVISED")){denied.put("revisedArguments",p.get("revisedArguments"));denied.put("revisedArgsHash",p.get("revisedArgsHash"));}store.save(PcTable.TOOL_CALL,call,denied);}
        evidence.audit(approval.getDirectoryContextId(),user,task.getId(),task.getSessionId(),"APPROVAL_DECISION",state,Map.of("approvalId",id,"argsHash",p.get("argsHash")));evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"APPROVAL_"+state,Map.of("approvalId",String.valueOf(id)));return store.view(approval);
    });}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> planAction(long user,long id,long version,String key,String action,Map<String,Object> input){return idem.run("user:"+user+":plan:"+id+":"+action,key,input,()->{
        PcRecord plan=access.resource(PcTable.PLAN,id,user,true,true);store.version(plan,version);Map<String,Object> p=store.data(plan);PcRecord task=store.require(PcTable.TASK,plan.getParentId(),true);if(store.data(task).get("importBatchId")!=null||!store.require(PcTable.SESSION,task.getSessionId(),false).getState().equals("ACTIVE"))throw new PcException(409,"PC_SESSION_READ_ONLY","历史计划只读，不能复活原执行");
        if(action.equals("execute")){access.approve(plan.getDirectoryContextId(),user);PcRunnerService.validateDag(PcRunnerService.steps(p));p.put("approvedVersion",definition(plan));plan.setState("APPROVED");}
        else if(action.equals("cancel")){plan.setState("CANCELLED");p.put("approvedVersion",0L);new PcSessionService(store,access,idem,evidence).cancel(task.getId(),user,task.getVersion(),key+":task-cancel");}
        else if(action.equals("revise")){String feedback=PcJson.text(input,"feedback");if(feedback.isBlank()||feedback.length()>8192)throw PcException.invalid("请填写修订要求");p.put("feedback",feedback);p.put("definitionVersion",definition(plan)+1);p.put("approvedVersion",0L);plan.setState("REVISION_REQUESTED");}
        else throw PcException.invalid("计划操作非法");store.save(PcTable.PLAN,plan,p);for(PcRecord a:store.mapper.list(PcTable.APPROVAL,task.getDirectoryContextId(),null,task.getId(),"PENDING")){a.setState("EXPIRED");store.save(PcTable.APPROVAL,a,store.data(a));}
        evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"PLAN_"+plan.getState(),Map.of("planId",String.valueOf(id),"planVersion",definition(plan)));return store.view(plan);
    });}
}
